import copy
from collections.abc import Mapping


class MaintenanceCard:
    _FIELDS = {
        "identity": {"asset_id", "location"},
        "work": {"notes", "parts", "labor_minutes"},
        "approval": {"approved", "audit"},
    }

    def __init__(self, asset_id, location="", notes=None, parts=None,
                 labor_minutes=0, approved=False, audit=None):
        values = {
            "asset_id": asset_id,
            "location": location,
            "notes": [] if notes is None else notes,
            "parts": {} if parts is None else parts,
            "labor_minutes": labor_minutes,
            "approved": approved,
            "audit": {} if audit is None else audit,
        }
        for name, value in values.items():
            self._validate(name, value)
        for name, value in values.items():
            setattr(self, name, copy.deepcopy(value))

    @staticmethod
    def _validate(name, value):
        if name in {"asset_id", "location"}:
            if not isinstance(value, str):
                raise TypeError(f"{name} must be a string")
        elif name == "notes":
            if not isinstance(value, list) or any(not isinstance(v, str) for v in value):
                raise TypeError("notes must be a list of strings")
        elif name == "parts":
            if not isinstance(value, dict):
                raise TypeError("parts must be a dictionary")
            for key, quantity in value.items():
                if not isinstance(key, str) or isinstance(quantity, bool) or not isinstance(quantity, int):
                    raise TypeError("invalid part entry")
                if quantity < 0:
                    raise ValueError("part quantities cannot be negative")
        elif name == "labor_minutes":
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError("labor_minutes must be an integer")
            if value < 0:
                raise ValueError("labor_minutes cannot be negative")
        elif name == "approved":
            if not isinstance(value, bool):
                raise TypeError("approved must be a boolean")
        elif name == "audit":
            if not isinstance(value, dict):
                raise TypeError("audit must be a dictionary")

    def apply_section(self, payload, section):
        if not isinstance(payload, Mapping):
            raise TypeError("payload must be a mapping")
        if section not in self._FIELDS:
            raise ValueError("unknown section")
        disallowed = set(payload) - self._FIELDS[section]
        if disallowed:
            raise KeyError(next(iter(disallowed)))
        staged = {}
        for name, value in payload.items():
            self._validate(name, value)
            staged[name] = value
        for name, value in staged.items():
            setattr(self, name, value)
        return self

